def count_patties(L, x, layers, patties):
    if x <= 0:
        return 0
    if L == 0:
        return 1  # x >= 1, it's a patty
    # Structure: 1 bun, layers[L-1] of burger, 1 patty, layers[L-1] of burger, 1 bun
    if x == 1:
        return 0  # just the bottom bun
    x -= 1  # consumed the bottom bun
    if x <= layers[L-1]:
        return count_patties(L-1, x, layers, patties)
    x -= layers[L-1]
    if x == 1:
        return patties[L-1] + 1  # all of first sub-burger + the middle patty
    x -= 1  # consumed the middle patty
    result = patties[L-1] + 1
    if x <= layers[L-1]:
        return result + count_patties(L-1, x, layers, patties)
