def count_moves(digits, d1, d2):
    s = list(digits)
    n = len(s)
    moves = 0

    # Find rightmost d2
    pos2 = -1
    for i in range(n-1, -1, -1):
        if s[i] == d2:
            pos2 = i
            break
    if pos2 == -1:
        return float('inf')

    # Bring d2 to end
    for i in range(pos2, n-1):
        s[i], s[i+1] = s[i+1], s[i]
        moves += 1

    # Find rightmost d1 in s[0..n-2]
    pos1 = -1
    for i in range(n-2, -1, -1):
        if s[i] == d1:
            pos1 = i
            break
    if pos1 == -1:
        return float('inf')

    # Bring d1 to second-to-last
    for i in range(pos1, n-2):
        s[i], s[i+1] = s[i+1], s[i]
        moves += 1

    # Handle leading zeros
    if s[0] == '0':
        # Find first non-zero digit
        for i in range(1, n):
            if s[i] != '0':
                # Bring it to front
                for j in range(i, 0, -1):
                    s[j], s[j-1] = s[j-1], s[j]
                    moves += 1
                break
        else:
            return float('inf')  # All zeros except last two

