def solve():
    MOD = 10**9 + 7
    N, K = map(int, input().split())

    def get_divisors(n):
        divs = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
            i += 1
        return divs

    def euler_phi(n):
        result = n
        p = 2
        temp = n
        while p * p <= temp:
            if temp % p == 0:
                while temp % p == 0:
                    temp //= p
                result -= result // p
            p += 1
        if temp > 1:
            result -= result // temp
        return result

    def orbits(d, N):
        # number of orbits of r <-> (N-1-r) mod d
        if d % 2 == 1:
            return (d + 1) // 2
        elif N % 2 == 1:
            return d // 2 + 1
        else:
            return d // 2

    def power(base, exp, mod):
        result = 1
        base %= mod
        while exp > 0:
            if exp % 2 == 1:
                result = result * base % mod
            base = base * base % mod
            exp //= 2
        return result

    divs = get_divisors(N)
    ans = 0
    inv_N = power(N, MOD - 2, MOD)

    for e in divs:
        phi_val = euler_phi(N // e)
        orb = orbits(e, N)
        ans = (ans + phi_val * power(K, orb, MOD)) % MOD

    ans = ans * inv_N % MOD
    print(ans)

