def comb_mod(n, k, MOD):
    if k < 0 or k > n:
        return 0
    num = 1
    for i in range(k):
        num = num * ((n - i) % MOD) % MOD
    # divide by k!
    fact_k = 1
    for i in range(1, k+1):
        fact_k = fact_k * i % MOD
    return num * pow(fact_k, MOD-2, MOD) % MOD

