def solve():
    line1 = input().split()
    n, m, d = int(line1[0]), int(line1[1]), int(line1[2])
    your = tuple(map(int, input().split()))
    opp = tuple(map(int, input().split()))

    @lru_cache(maxsize=None)
    def dp(dmg, your_m, opp_m):
        if not opp_m:
            return 1.0
        if dmg == 0:
            return 0.0
        total = len(your_m) + len(opp_m)
        prob = 0.0
        p = 1.0 / total
        # Hit each of your minions
        for i in range(len(your_m)):
            new_h = your_m[i] - 1
            if new_h == 0:
                new_your = your_m[:i] + your_m[i+1:]
            else:
                new_your = your_m[:i] + (new_h,) + your_m[i+1:]
            prob += p * dp(dmg - 1, new_your, opp_m)
        # Hit each opponent minion
        for i in range(len(opp_m)):
            new_h = opp_m[i] - 1
            if new_h == 0:
                new_opp = opp_m[:i] + opp_m[i+1:]
            else:
                new_opp = opp_m[:i] + (new_h,) + opp_m[i+1:]
            prob += p * dp(dmg - 1, your_m, new_opp)
        return prob

    result = dp(d, your, opp)
    print(f"{result:.10f}")

