from fractions import Fraction

def compute_prob(N, k):
    total = comb(N, 3)
    prob = Fraction(0)
    for s in range(4):
        if s > k or (3-s) > (N-k):
            continue
        ways = comb(k, s) * comb(N-k, 3-s)
        if s == 0:
            p_s = Fraction(0)
        elif s == 1:
            p_s = Fraction(1, 2)
        else:
            p_s = Fraction(1)
        prob += Fraction(ways, total) * p_s
    return prob

