def factorize(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def multiplicative_order(x, n):
    # order of x mod n, assuming gcd(x,n)=1
    phi = euler_phi_from_factors(factorize(n))
    order = phi
    for p, _ in factorize(phi).items():
        while order % p == 0 and pow(x, order // p, n) == 1:
            order //= p
    return order

def euler_phi_from_factors(factors):
    result = 1
    for p, e in factors.items():
        result *= (p - 1) * p ** (e - 1)
    return result

def get_divisors(factors):
