    parity = []
    for x in p:
        if x == 0:
            parity.append(-1)
        else:
            parity.append(x % 2)

    # dp[i][j] = min complexity for first i elements, j odds used among zeros
    INF = float('inf')
    # dp indexed by previous parity (0 or 1) and odds_used
    # Let's do iterative DP
    # dp[prev_par][odds_used] = min cost

    total_zeros = parity.count(-1)

    # Initialize
    dp = [[INF] * (missing_odds + 1) for _ in range(2)]

    # Process first element
    if parity[0] == -1:
        if missing_odds > 0:
            dp[1][1] = 0
        if missing_evens > 0:
            dp[0][0] = 0
    else:
        dp[parity[0]][0] = 0

    zeros_seen = 1 if parity[0] == -1 else 0

    for i in range(1, n):
        new_dp = [[INF] * (missing_odds + 1) for _ in range(2)]
        for prev in range(2):
            for j in range(missing_odds + 1):
                if dp[prev][j] == INF:
                    continue
                evens_used = zeros_seen - j  # zeros seen before this position
                if parity[i] == -1:
