import sys

def solve():
    MOD = 10**9 + 7
    n, k = map(int, input().split())

    # Precompute divisors for each number 1..n
    divisors = [[] for _ in range(n + 1)]
    for m in range(1, n + 1):
        for j in range(m, n + 1, m):
            divisors[j].append(m)

    # dp[j] = number of good sequences of current length ending with j
    dp = [0] * (n + 1)
    for j in range(1, n + 1):
        dp[j] = 1

    for i in range(1, k):
        new_dp = [0] * (n + 1)
        for j in range(1, n + 1):
            s = 0
            for m in divisors[j]:
                s += dp[m]
            new_dp[j] = s % MOD
        dp = new_dp

    print(sum(dp[1:n+1]) % MOD)

solve()

