from collections import Counter
from itertools import product

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    cnt = Counter(a)
    distinct = sorted(cnt.keys())
    counts = [cnt[v] for v in distinct]

    best = 0
    # Try all k, m
    total_sum = sum(a)
    for k in range(0, n+1):
        for m in range(0, total_sum+1):
            # Find all valid multisets
            valid = []
            def rec(idx, rem_k, rem_m, chosen):
                if rem_k == 0 and rem_m == 0:
                    valid.append(tuple(chosen))
                    return
                if idx == len(distinct) or rem_k < 0 or rem_m < 0:
                    return
                for c in range(0, min(counts[idx], rem_k)+1):
                    if distinct[idx]*c <= rem_m:
                        rec(idx+1, rem_k-c, rem_m-distinct[idx]*c, chosen+[c])
            rec(0, k, m, [])
            if not valid:
                continue
            revealed = 0
            for i, v in enumerate(distinct):
                in_query = [vs[i] for vs in valid]
                if len(set(in_query)) == 1:
                    revealed += counts[i]  # all of this mass revealed
            best = max(best, revealed)
    print(best)

solve()

def count_black(r0, c0, rows, cols):
    if rows <= 0 or cols <= 0:
        return 0
    total = rows * cols
    # upper-left corner is (r0, c0), black if (r0+c0)%2==0
    if (r0 + c0) % 2 == 0:
        return (total + 1) // 2
    else:
        return total // 2

