import sys

def solve():
    input_data = sys.stdin.read().split()
    n, k = int(input_data[0]), int(input_data[1])
    s = input_data[2]
    t = input_data[3]

    NEG_INF = -1
    # dp[j][c] = max subseq count, j moves used, c t[0]s placed
    dp = [[NEG_INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(n):
        new_dp = [[NEG_INF] * (n + 1) for _ in range(k + 1)]
        for j in range(k + 1):
            for c in range(i + 1):
                if dp[j][c] == NEG_INF:
                    continue
                val = dp[j][c]
                # Option 1: make s[i] -> t[0]
                cost1 = 0 if s[i] == t[0] else 1
                if j + cost1 <= k:
                    nc = c + 1
                    if new_dp[j+cost1][nc] < val:
                        new_dp[j+cost1][nc] = val
                # Option 2: make s[i] -> t[1]
                cost2 = 0 if s[i] == t[1] else 1
                if j + cost2 <= k:
                    if new_dp[j+cost2][c] < val + c:
                        new_dp[j+cost2][c] = val + c
                # Option 3: neutral (only free if s[i] not t[0] or t[1])
                if s[i] != t[0] and s[i] != t[1]:
                    if new_dp[j][c] < val:
                        new_dp[j][c] = val
        dp = new_dp

    ans = 0
    for j in range(k+1):
        for c in range(n+1):
            if dp[j][c] > ans:
                ans = dp[j][c]
    print(ans)

solve()

