def solve():
    MOD = 10**13
    f = int(input())

    # Fast doubling mod m
    def fib_pair(n, m):
        if n == 0:
            return (0, 1)
        a, b = fib_pair(n >> 1, m)
        c = a * (2*b - a) % m
        d = (a*a + b*b) % m
        if n & 1:
            return (d, (c+d) % m)
        return (c, d)

    def fib(n, m):
        return fib_pair(n, m)[0]

    # Find all positions in [0, period) where F(pos) ≡ f (mod current_mod)
    # Start with mod 10, period 60
    current_mod = 10
    period = 60
    candidates = []
    for i in range(period):
        if fib(i, current_mod) == f % current_mod:
            candidates.append(i)

    # Lift up to 10^13
    for k in range(1, 13):
        next_mod = current_mod * 10
        next_period = period * 10
        new_candidates = []
        for c in candidates:
            for j in range(10):
                pos = c + j * period
                if fib(pos, next_mod) == f % next_mod:
                    new_candidates.append(pos)
        candidates = new_candidates
        current_mod = next_mod
        period = next_period

    if not candidates:
        print(-1)
    else:
        print(min(candidates))

solve()

